    #[test]
    fn scoped_claim_and_overlap_round_trip_through_tools() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Scoped work", "avoid overlap", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Edit graph", "done").unwrap();
        let task_id = task.id.clone();

        let claimed = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": task_id,
                    "step": "claim",
                    "agent": "alice",
                    "lease_secs": 300,
                    "paths": ["crates/mindleak-core/src/**"],
                    "symbols": ["symbol:crates/mindleak-core/src/lib.rs:MindLeak"]
                }
            }),
        )
        .unwrap();
        assert!(claimed["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("true"));

        let overlap = call(
            &engine,
            &json!({
                "name": "task_query",
                "arguments": {
                    "view": "overlap",
                    "paths": ["crates/mindleak-core/src/lib.rs"],
                    "symbols": ["symbol:crates/mindleak-core/src/lib.rs:MindLeak"]
                }
            }),
        )
        .unwrap();
        let body: Value =
            serde_json::from_str(overlap["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(body["claims"].as_array().unwrap().len(), 1);
        assert_eq!(body["claims"][0]["owner"], "alice");
        // Nobody declared a branch, so the answer is exactly the one this tool
        // has always given, and it says so rather than implying a verdict.
        assert!(body["requester_branch"].is_null());
        assert_eq!(body["claims"][0]["signal"], "undeclared");

        let board = call(
            &engine,
            &json!({
                "name": "task_query",
                "arguments": { "view": "board", "include_terminal": false }
            }),
        )
        .unwrap();
        let rows: Value =
            serde_json::from_str(board["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(rows[0]["scope"]["paths"][0], "crates/mindleak-core/src/**");
        assert_eq!(
            rows[0]["scope"]["symbols"][0],
            "symbol:crates/mindleak-core/src/lib.rs:MindLeak"
        );
    }

    #[test]
    fn won_scoped_claim_carries_the_memory_preflight_and_other_claims_stay_quiet() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Memory", "read before editing", None)
            .unwrap();
        let scoped = engine.create_task(&goal.id, "Scoped", "done").unwrap();

        let claimed = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": scoped.id,
                    "step": "claim",
                    "agent": "alice",
                    "paths": ["src/auth.rs"],
                    "symbols": ["symbol:src/auth.rs:verify"]
                }
            }),
        )
        .unwrap();
        let body: Value =
            serde_json::from_str(claimed["content"][0]["text"].as_str().unwrap()).unwrap();

        // ADR-0066's separate call was routinely skipped. The claim agents do
        // make must hand them the exact cross-plane read without pretending it ran.
        assert_eq!(body["memory_preflight"]["plane"], "mindleak");
        assert_eq!(body["memory_preflight"]["tool"], "check_overlap");
        assert_eq!(body["memory_preflight"]["when"], "before the first edit");
        assert_eq!(body["memory_preflight"]["advisory"], true);
        assert_eq!(
            body["memory_preflight"]["arguments"]["paths"],
            json!(["src/auth.rs"])
        );
        assert_eq!(
            body["memory_preflight"]["arguments"]["symbols"],
            json!(["symbol:src/auth.rs:verify"])
        );

        let unscoped = engine.create_task(&goal.id, "Unscoped", "done").unwrap();
        let unscoped_claim = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": { "task_id": unscoped.id, "step": "claim", "agent": "bob" }
            }),
        )
        .unwrap();
        let unscoped_body: Value =
            serde_json::from_str(unscoped_claim["content"][0]["text"].as_str().unwrap()).unwrap();
        assert!(unscoped_body.get("memory_preflight").is_none());

        let held = engine.create_task(&goal.id, "Held", "done").unwrap();
        assert!(engine.claim_task(&held.id, "alice", 300).unwrap());
        let lost = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": held.id,
                    "step": "claim",
                    "agent": "bob",
                    "paths": ["src/auth.rs"]
                }
            }),
        )
        .unwrap();
        let lost_body: Value =
            serde_json::from_str(lost["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(lost_body["won"], false);
        assert!(lost_body.get("memory_preflight").is_none());
    }

    /// ADR-0035 decision 5: the claim decision surfaces the branch. A won claim
    /// confirms the branch its window was pinned to; a lost claim names not just
    /// who holds the task but the branch they hold it on — the fact a colliding
    /// agent needs to tell a merge risk from the same work twice. Both come from
    /// what the owner declared to `open_session`.
    #[test]
    fn the_claim_decision_surfaces_the_branch_when_declared() {
        use mindleak_session::SessionContext;
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(
                GoalKind::Objective,
                "Surface branch",
                "fleet feedback",
                None,
            )
            .unwrap();
        let task = engine
            .create_task(&goal.id, "Edit executive", "done")
            .unwrap();
        let task_id = task.id.clone();

        // The owner declared a branch at open_session; the claim pins it.
        engine
            .declare_session_context(
                "alice",
                &SessionContext {
                    branch: Some("fleet/surface".to_string()),
                    ..Default::default()
                },
            )
            .unwrap();

        let won = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": task_id,
                    "step": "claim",
                    "agent": "alice",
                    "lease_secs": 300
                }
            }),
        )
        .unwrap();
        let won_body: Value =
            serde_json::from_str(won["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(won_body["won"], true);
        // The won claim confirms the branch its window was pinned to.
        assert_eq!(won_body["branch"], "fleet/surface");

        // A different agent loses, and learns which branch the holder is on.
        let lost = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": task_id,
                    "step": "claim",
                    "agent": "bob",
                    "lease_secs": 300
                }
            }),
        )
        .unwrap();
        let lost_body: Value =
            serde_json::from_str(lost["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(lost_body["won"], false);
        assert_eq!(lost_body["owner"], "alice");
        assert_eq!(lost_body["owner_branch"], "fleet/surface");
    }

    /// The surfacing omits cleanly when no branch was declared, rather than
    /// guessing one — the server never inspects Git (ADR-0044). Carried as an
    /// explicit null, the way board rows carry `owner: null`: "declared
    /// nothing", not "the key is missing".
    #[test]
    fn the_claim_decision_omits_the_branch_when_none_was_declared() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "No branch", "fleet feedback", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Edit", "done").unwrap();

        let won = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": task.id,
                    "step": "claim",
                    "agent": "carol",
                    "lease_secs": 300
                }
            }),
        )
        .unwrap();
        let body: Value =
            serde_json::from_str(won["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(body["won"], true);
        assert!(body["branch"].is_null());
    }

    #[test]
    fn checked_conformance_completes_with_one_authoritative_audit() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship search", "add search", None)
            .unwrap();
        let node_id = "artifact:src/search.rs";
        engine
            .link_goal_to_artifact(&goal.id, &[node_id.into()], ArtifactBindingMode::Governed)
            .unwrap();
        let task = engine.create_task(&goal.id, "wire search", "done").unwrap();
        engine.claim_task(&task.id, "agent-a", 300).unwrap();
        let claimed = engine.store().get_task(&task.id).unwrap().unwrap();
        let evidence = json!({
            "schema_version": 1,
            "task_id": task.id,
            "agent_id": "agent-a",
            "started_at": claimed.claim_started_at.unwrap(),
            "ended_at": now_unix(),
            "changed_node_ids": [node_id],
            "failed_node_ids": [],
            "execution_ids": ["execution:proof"],
            "successful_execution_ids": ["execution:proof"],
            "commit_ids": [],
            "summary": "wired search",
            "provenance": [
                {
                    "source_id": "agent:agent-a",
                    "target_id": "execution:proof",
                    "relation": "observed"
                },
                {
                    "source_id": "execution:proof",
                    "target_id": node_id,
                    "relation": "modified"
                }
            ]
        });

        let checked_response = call(
            &engine,
            &json!({
                "name": "check_conformance",
                "arguments": { "task_id": task.id, "evidence": evidence }
            }),
        )
        .unwrap();
        let checked: Value =
            serde_json::from_str(checked_response["content"][0]["text"].as_str().unwrap()).unwrap();
        assert!(checked["id"].as_i64().unwrap() > 0);
        assert_eq!(checked["token"].as_str().unwrap().len(), 64);
        assert_eq!(checked["verdict"], "aligned");

        let completed_response = call(
            &engine,
            &json!({
                "name": "task_transition",
                "arguments": {
                    "task_id": task.id,
                    "to": "complete",
                    "agent": "agent-a",
                    "evidence": evidence,
                    "check": {
                        "id": checked["id"],
                        "token": checked["token"]
                    }
                }
            }),
        )
        .unwrap();
        let completed: Value =
            serde_json::from_str(completed_response["content"][0]["text"].as_str().unwrap())
                .unwrap();
        assert_eq!(completed["completed"], true);
        assert_eq!(completed["conformance"]["verdict"], "aligned");
        assert_eq!(engine.conformance_history(&task.id).unwrap().len(), 1);
    }

