    #[test]
    fn check_overlap_dispatch_grades_the_collision_by_declared_branch() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Graded", "grade the overlap", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Edit graph", "done").unwrap();
        assert!(engine
            .claim_task_with_scope(
                &task.id,
                "alice",
                300,
                &lodestar_core::TaskScope {
                    paths: vec!["crates/mindleak-core/src/**".to_string()],
                    symbols: vec![],
                },
            )
            .unwrap());
        let on_branch = |branch: &str| mindleak_session::SessionContext {
            branch: Some(branch.to_string()),
            ..mindleak_session::SessionContext::default()
        };
        engine
            .declare_session_context("alice", &on_branch("fleet/a"))
            .unwrap();

        let signal = |agent: &str| {
            let result = call(
                &engine,
                &json!({
                    "name": "task_query",
                    "arguments": {
                        "view": "overlap",
                        "paths": ["crates/mindleak-core/src/lib.rs"],
                        // Injected by `bind_session` from the offered session.
                        "agent": agent
                    }
                }),
            )
            .unwrap();
            serde_json::from_str::<Value>(result["content"][0]["text"].as_str().unwrap()).unwrap()
        };

        engine
            .declare_session_context("bob", &on_branch("fleet/a"))
            .unwrap();
        let same = signal("bob");
        assert_eq!(same["requester_branch"], "fleet/a");
        assert_eq!(same["claims"][0]["owner_branch"], "fleet/a");
        assert_eq!(same["claims"][0]["signal"], "same_branch_collision");

        engine
            .declare_session_context("bob", &on_branch("fleet/b"))
            .unwrap();
        let different = signal("bob");
        assert_eq!(different["claims"][0]["signal"], "cross_branch_merge_risk");

        // Still advisory: the graded answer changed nothing about the claim.
        assert_eq!(
            engine.board(false).unwrap()[0].owner.as_deref(),
            Some("alice")
        );
    }

    #[test]
    fn recover_claim_dispatch_exposes_the_append_only_transfer() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Recover", "transfer legacy work", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Legacy", "done").unwrap();
        assert!(engine.claim_task(&task.id, "copilot-abcd1234", -1).unwrap());
        let agent = SessionRegistry::new("copilot")
            .unwrap()
            .open_session(
                "00112233445566778899aabbccddeeff",
                mindleak_session::SessionContext::default(),
            )
            .unwrap()
            .agent_id;

        let recovered = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": task.id,
                    "step": "recover",
                    "expected_owner": "copilot-abcd1234",
                    "agent": agent,
                    // Injected by `bind_session` in the running server. Since
                    // ADR-0054 the id carries no label, so the name the
                    // recovering session declares is what the legacy owner is
                    // matched against.
                    "resolved_name": "copilot",
                    "reason": "legacy process exited",
                    "lease_secs": 300
                }
            }),
        )
        .unwrap();
        let payload: Value =
            serde_json::from_str(recovered["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(payload["recovered"], true);

        let history = call(
            &engine,
            &json!({
                "name": "task_query",
                "arguments": { "view": "claim_transfers", "task_id": task.id }
            }),
        )
        .unwrap();
        let transfers: Value =
            serde_json::from_str(history["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(transfers.as_array().unwrap().len(), 1);
        assert_eq!(transfers[0]["from_owner"], "copilot-abcd1234");
        assert_eq!(transfers[0]["to_owner"], agent);
    }

    #[test]
    fn recover_claim_dispatch_requires_a_human_for_early_paused_transfer() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Recover", "transfer paused work", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Paused", "done").unwrap();
        let old_owner = "session:v1:old";
        let new_owner = "session:v1:new";
        assert!(engine.claim_task(&task.id, old_owner, 600).unwrap());
        assert!(engine
            .pause_task(&task.id, old_owner, Some("owner process exited"))
            .unwrap());

        let without_human = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": task.id,
                    "step": "recover",
                    "expected_owner": old_owner,
                    "agent": new_owner,
                    "resolved_name": "copilot",
                    "reason": "continue the work"
                }
            }),
        )
        .unwrap_err();
        assert!(without_human.contains("human reviewer"), "{without_human}");

        let recovered = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": task.id,
                    "step": "recover",
                    "expected_owner": old_owner,
                    "agent": new_owner,
                    "resolved_name": "copilot",
                    "reason": "owner is gone; continue the work",
                    "human": "lyndon",
                    "lease_secs": 300
                }
            }),
        )
        .unwrap();
        let payload: Value =
            serde_json::from_str(recovered["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(payload["recovered"], true);

        let transfers = engine.claim_transfer_history(&task.id).unwrap();
        assert_eq!(transfers[0].from_owner, old_owner);
        assert_eq!(transfers[0].to_owner, new_owner);
        assert_eq!(transfers[0].recovered_by, "lyndon");
    }

    #[test]
    fn resolve_task_dispatch_human_accepts_an_in_review_task() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship auth", "change auth", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "change auth", "done").unwrap();
        engine.claim_task(&task.id, "agent-a", 300).unwrap();
        let started = engine
            .board(true)
            .unwrap()
            .into_iter()
            .find(|t| t.id == task.id)
            .unwrap()
            .claim_started_at
            .unwrap();
        let evidence = ConformanceEvidence {
            schema_version: 1,
            task_id: Some(task.id.clone()),
            agent_id: "agent-a".into(),
            started_at: started,
            ended_at: now_unix(),
            changed_node_ids: Vec::new(),
            failed_node_ids: Vec::new(),
            execution_ids: Vec::new(),
            successful_execution_ids: Vec::new(),
            commit_ids: Vec::new(),
            summary: "no mutation evidence".into(),
            provenance: Vec::new(),
        };
        let checked = engine.check_conformance(&evidence, Some(&task.id)).unwrap();
        engine
            .complete_task(&task.id, "agent-a", &evidence, &checked, None)
            .unwrap();

        // The reviewed agent may not sign off on its own work.
        let denied = call(
            &engine,
            &json!({ "name": "task_transition", "arguments": { "task_id": task.id, "to": "resolve", "human": "agent-a" } }),
        );
        assert!(denied.unwrap_err().contains("may not resolve its own"));

        // Any distinct non-empty label is accepted and attributed. This is
        // deliberately not a known principal or credential: ADR-0071 requires
        // the API to stop implying authentication it cannot perform.
        let reviewer_label = "reviewed-by-lyndon (unverified label)";
        let result = call(
            &engine,
            &json!({ "name": "task_transition", "arguments": { "task_id": task.id, "to": "resolve", "human": reviewer_label } }),
        )
        .unwrap();
        let payload: Value =
            serde_json::from_str(result["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(payload["resolved"], true);

        let board = engine.board(true).unwrap();
        let resolved = board.iter().find(|t| t.id == task.id).unwrap();
        assert_eq!(resolved.status.as_str(), "done");
        assert_eq!(resolved.resolved_by.as_deref(), Some(reviewer_label));

        let definition = definitions()
            .into_iter()
            .find(|tool| tool["name"] == "task_transition")
            .unwrap();
        let description = definition["inputSchema"]["properties"]["human"]["description"]
            .as_str()
            .unwrap();
        assert!(description.contains("not authenticated"), "{description}");
    }

    #[test]
    fn board_tool_filters_terminal_tasks_when_requested() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "do it", None)
            .unwrap();
        let live = engine.create_task(&goal.id, "Live", "").unwrap();
        let retired = engine.create_task(&goal.id, "Retired", "").unwrap();
        engine.abandon_task(&retired.id, false).unwrap();

        // Default: every task, including the abandoned one.
        let all: Value = serde_json::from_str(
            call(
                &engine,
                &json!({ "name": "task_query", "arguments": { "view": "board" } }),
            )
            .unwrap()["content"][0]["text"]
                .as_str()
                .unwrap(),
        )
        .unwrap();
        assert!(all
            .as_array()
            .unwrap()
            .iter()
            .any(|task| task["id"] == retired.id));

        // Opt into the lean view: terminal tasks drop out, live work remains.
        let active: Value = serde_json::from_str(
            call(
                &engine,
                &json!({ "name": "task_query", "arguments": { "view": "board", "include_terminal": false } }),
            )
            .unwrap()["content"][0]["text"]
                .as_str()
                .unwrap(),
        )
        .unwrap();
        let ids: Vec<&str> = active
            .as_array()
            .unwrap()
            .iter()
            .map(|task| task["id"].as_str().unwrap())
            .collect();
        assert!(ids.contains(&live.id.as_str()));
        assert!(!ids.contains(&retired.id.as_str()));
    }

    /// Bug: `status: claimed` was the only state the board exposed, so a row
    /// whose lease expired hours ago read exactly like work in progress.
    /// Measured once at 36 claimed rows with 4 live leases, making every plan
    /// against the board nine times wrong. The lease state is derived where the
    /// board is read rather than by rewriting durable task status (ADR-0067).
    #[test]
    fn board_tool_distinguishes_a_live_claim_from_a_lapsed_one() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "do it", None)
            .unwrap();
        let live = engine.create_task(&goal.id, "Live lease", "").unwrap();
        let lapsed = engine.create_task(&goal.id, "Lapsed lease", "").unwrap();
        assert!(engine.claim_task(&live.id, "alice", 600).unwrap());
        assert!(engine.claim_task(&lapsed.id, "bob", -1).unwrap());

        let board: Value = serde_json::from_str(
            call(
                &engine,
                &json!({ "name": "task_query", "arguments": { "view": "board" } }),
            )
            .unwrap()["content"][0]["text"]
                .as_str()
                .unwrap(),
        )
        .unwrap();
        let row = |id: &str| {
            board
                .as_array()
                .unwrap()
                .iter()
                .find(|task| task["id"] == id)
                .unwrap()
        };
        assert_eq!(row(&live.id)["lease_state"], "live");
        assert_eq!(row(&lapsed.id)["lease_state"], "lapsed");
    }

    #[test]
    fn create_task_rejects_malformed_predecessor_and_preserves_legacy_calls() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Handoff", "serialize edits", None)
            .unwrap();
        let malformed = json!({
            "name": "task_create",
            "arguments": {
                "goal_id": goal.id,
                "title": "Unsafe",
                "blocked_by": 42
            }
        });
        assert!(call(&engine, &malformed)
            .unwrap_err()
            .contains("must be a string"));

        let legacy = call(
            &engine,
            &json!({
                "name": "task_create",
                "arguments": { "goal_id": goal.id, "title": "Legacy" }
            }),
        )
        .unwrap();
        let task: Value =
            serde_json::from_str(legacy["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(task["status"], "open");
        assert!(task["blocked_by"].is_null());
    }

    /// A lapse is silent until `complete_task`, which is far too late: closing
    /// a lapsed claim means re-claiming it, re-claiming records the lapse, and
    /// conformance then refuses to certify across the hole (ADR-0048). The only
    /// warning arrived after the cost had already become unrecoverable.
    /// Twenty-nine claims on this repository are stuck behind exactly that.
    #[test]
    fn a_lease_about_to_expire_says_so_while_there_is_still_time() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Work", "done").unwrap();
        assert!(engine.claim_task(&task.id, "agent-a", 30).unwrap());

        let mut response = json!({});
        attach_lease_warning(&engine, &json!({ "agent": "agent-a" }), &mut response).unwrap();

        let expiring = response["lease_expiring"]
            .as_array()
            .expect("an imminent deadline is reported");
        assert_eq!(expiring.len(), 1);
        assert_eq!(expiring[0]["task_id"], task.id);
        let advice = response["lease_advice"].as_str().unwrap();
        assert!(
            advice.contains("task_claim with step=\"renew\""),
            "names the fix: {advice}"
        );
        assert!(
            advice.contains("ADR-0048"),
            "says why missing it cannot be repaired later: {advice}"
        );
    }

    /// The urgent case, and the one originally left out. The damage is done,
    /// but the sooner an agent knows, the sooner it stops building work it can
    /// never certify -- and the advice must not be "renew", which cannot repair
    /// a window that already has a hole in it.
    #[test]
    fn an_already_lapsed_lease_says_renewing_will_not_repair_it() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Work", "done").unwrap();
        assert!(engine.claim_task(&task.id, "agent-a", -10).unwrap());

        let mut response = json!({});
        attach_lease_warning(&engine, &json!({ "agent": "agent-a" }), &mut response).unwrap();

        assert_eq!(response["lease_lapsed"].as_array().unwrap().len(), 1);
        let advice = response["lapsed_advice"].as_str().unwrap();
        assert!(
            advice.contains("Renewing will not repair it"),
            "stops the obvious wrong response: {advice}"
        );
        assert!(
            advice.contains("human"),
            "names who can actually resolve it: {advice}"
        );
        assert!(
            response.get("lease_expiring").is_none(),
            "a dead lease is not an expiring one: {response}"
        );
    }

    /// Warning on every call trains agents to ignore the field, which is how a
    /// real warning gets missed. A comfortable lease says nothing at all.
    #[test]
    fn a_comfortable_lease_stays_quiet() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Work", "done").unwrap();
        assert!(engine.claim_task(&task.id, "agent-a", 3600).unwrap());

        let mut response = json!({});
        attach_lease_warning(&engine, &json!({ "agent": "agent-a" }), &mut response).unwrap();
        assert_eq!(response, json!({}), "silent: {response}");
    }

    /// Another agent's deadline is not this agent's problem, and reporting it
    /// would be noise attached to someone else's work.
    #[test]
    fn only_your_own_lease_is_reported() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let theirs = engine.create_task(&goal.id, "Theirs", "done").unwrap();
        let mine = engine.create_task(&goal.id, "Mine", "done").unwrap();
        assert!(engine.claim_task(&theirs.id, "agent-a", 30).unwrap());
        assert!(engine.claim_task(&mine.id, "agent-b", 3600).unwrap());

        let mut response = json!({});
        attach_lease_warning(&engine, &json!({ "agent": "agent-b" }), &mut response).unwrap();
        assert_eq!(response, json!({}), "not mine: {response}");
    }

    /// A lost claim used to be a bare `won: false`. The reasons it can fail
    /// call for opposite responses -- wait for a lease, pick different work,
    /// unblock a predecessor, rebuild a stale binary -- so one boolean covering
    /// all of them is not terse, it is unusable. `scripts/claim-gate.mjs` is a
    /// whole diagnostic written to reconstruct after the fact what the plane
    /// knew at the moment it refused.
    #[test]
    fn a_lost_claim_says_why_and_what_to_do_about_it() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let held = engine.create_task(&goal.id, "Theirs", "done").unwrap();
        assert!(engine.claim_task(&held.id, "agent-a", 600).unwrap());

        let lost = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": { "task_id": held.id, "step": "claim", "agent": "agent-b" }
            }),
        )
        .unwrap();
        let body: Value =
            serde_json::from_str(lost["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(body["won"], false);
        let reason = body["reason"]
            .as_str()
            .expect("a lost claim reports a reason");
        assert!(reason.contains("agent-a"), "names the holder: {reason}");
        assert!(
            reason.contains("task_claim with step=\"recover\""),
            "names the verb that can take it: {reason}"
        );
        assert_eq!(
            body["owner"], "agent-a",
            "the holder is machine-readable too"
        );

        // Finished work and missing work are different refusals, and neither is
        // "wait for the lease".
        let finished = engine.create_task(&goal.id, "Shipped", "done").unwrap();
        engine.abandon_task(&finished.id, false).unwrap();
        let on_terminal = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": { "task_id": finished.id, "step": "claim", "agent": "agent-b" }
            }),
        )
        .unwrap();
        let terminal: Value =
            serde_json::from_str(on_terminal["content"][0]["text"].as_str().unwrap()).unwrap();
        assert!(
            terminal["reason"]
                .as_str()
                .unwrap()
                .contains("nothing to claim"),
            "terminal work says so: {terminal}"
        );

        let missing = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": { "task_id": "task:nope", "step": "claim", "agent": "agent-b" }
            }),
        )
        .unwrap();
        let absent: Value =
            serde_json::from_str(missing["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(absent["reason"], "no such task");
    }

    /// The expensive one. A server built before ADR-0054 resolves a different
    /// identity shape than the migrated ledger holds, so an agent is refused
    /// its own claim and re-claiming never helps. Nothing in `won: false`
    /// hinted at it, and the hunt cost hours.
    #[test]
    fn a_claim_refused_by_a_stale_binary_names_the_binary() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Mine", "done").unwrap();
        assert!(engine.claim_task(&task.id, "copilot", 600).unwrap());

        let lost = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": task.id,
                    "step": "claim",
                    "agent": "session:v1:bff9bbe3968f16636cbc5522086114e3"
                }
            }),
        )
        .unwrap();
        let body: Value =
            serde_json::from_str(lost["content"][0]["text"].as_str().unwrap()).unwrap();
        let reason = body["reason"].as_str().unwrap();
        assert!(reason.contains("ADR-0054"), "names the decision: {reason}");
        assert!(
            reason.contains("re-claiming will not help"),
            "stops the obvious wrong response: {reason}"
        );
        assert!(
            reason.contains("Rebuild"),
            "names the actual remedy: {reason}"
        );
    }

    // ADR-0060: `complete_task` refuses evidence whose `started_at` precedes
    // `claim_started_at` with "evidence interval falls outside the live claim",
    // and no tool returned that value - `claim_task` gave back only `won` and
    // `governing`, and `task_scope` only `paths` and `symbols`. So the one
    // number needed to build acceptable evidence was unobtainable, an agent had
    // to guess it, and a wrong guess read as a policy refusal rather than a
    // missing accessor. The claim now returns the window it opened.
    #[test]
    fn a_won_claim_returns_the_evidence_window_it_opened() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Work", "done").unwrap();

        let claimed = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": { "task_id": task.id, "step": "claim", "agent": "agent-a", "lease_secs": 600 }
            }),
        )
        .unwrap();
        let body: Value =
            serde_json::from_str(claimed["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(body["won"], true);

        let window = body["claim_started_at"]
            .as_i64()
            .expect("a won claim reports the start of the window evidence is judged against");
        assert!(window > 0);
        assert_eq!(
            window,
            engine
                .store()
                .get_task(&task.id)
                .unwrap()
                .unwrap()
                .claim_started_at
                .unwrap(),
            "the reported window must be the one the store will validate against"
        );
        assert!(
            body["lease_expires_at"].as_i64().unwrap() >= window,
            "the lease cannot expire before the claim began"
        );

        // A lost claim has no window to report, so it must not invent one.
        let lost = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": { "task_id": task.id, "step": "claim", "agent": "agent-b" }
            }),
        )
        .unwrap();
        let lost_body: Value =
            serde_json::from_str(lost["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(lost_body["won"], false);
        assert!(lost_body.get("claim_started_at").is_none());
    }

    // ADR-0046: an addressed question is a durable row a peer must ask for, so
    // a peer who never asks never learns. Delivering it on the calls an agent
    // already makes - pickup and heartbeat - is the difference between a
    // capability and an adopted one; the whole intent plane measured zero
    // adoption while participation was a separate thing to remember.
    #[test]
    fn a_question_addressed_to_you_arrives_on_pickup_and_on_the_heartbeat() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship it", "ship", None)
            .unwrap();
        let theirs = engine.create_task(&goal.id, "their work", "done").unwrap();
        let mine = engine.create_task(&goal.id, "my work", "done").unwrap();
        let paused = engine.create_task(&goal.id, "paused work", "done").unwrap();

        // agent-b parks its own task on a question addressed to agent-a.
        assert!(engine.claim_task(&theirs.id, "agent-b", 600).unwrap());
        assert!(engine
            .ask_question(&theirs.id, "agent-b", "did you rename it?", Some("agent-a"))
            .unwrap());
        assert!(engine.claim_task(&paused.id, "agent-a", 600).unwrap());
        assert!(engine
            .pause_task(&paused.id, "agent-a", Some("waiting for CI"))
            .unwrap());

        // agent-a picks up unrelated work and is told, without asking.
        let claimed = call(
            &engine,
            &json!({ "name": "task_claim", "arguments": { "task_id": mine.id, "step": "claim", "agent": "agent-a" } }),
        )
        .unwrap();
        let body: Value =
            serde_json::from_str(claimed["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(body["won"], true);
        assert_eq!(body["waiting_on_you"][0]["task_id"], theirs.id);
        assert_eq!(body["waiting_on_you"][0]["body"], "did you rename it?");
        assert_eq!(body["paused_by_you"][0]["task_id"], paused.id);
        assert_eq!(body["paused_by_you"][0]["reason"], "waiting for CI");

        // The heartbeat matters more than pickup: a question usually arrives
        // during the work, long after the claim.
        let renewed = call(
            &engine,
            &json!({ "name": "task_claim", "arguments": { "task_id": mine.id, "step": "renew", "agent": "agent-a" } }),
        )
        .unwrap();
        let beat: Value =
            serde_json::from_str(renewed["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(beat["renewed"], true);
        assert_eq!(beat["waiting_on_you"][0]["task_id"], theirs.id);
        assert_eq!(beat["paused_by_you"][0]["task_id"], paused.id);

        // Nobody asked agent-c anything, so agent-c is told nothing at all -
        // no key, no empty array. "No questions" and "this server does not
        // report questions" must not look the same to a reader.
        let other = engine.create_task(&goal.id, "other work", "done").unwrap();
        let quiet = call(
            &engine,
            &json!({ "name": "task_claim", "arguments": { "task_id": other.id, "step": "claim", "agent": "agent-c" } }),
        )
        .unwrap();
        let quiet_body: Value =
            serde_json::from_str(quiet["content"][0]["text"].as_str().unwrap()).unwrap();
        assert!(quiet_body.get("waiting_on_you").is_none());

        // Once answered it stops arriving, or the delivery becomes noise the
        // agent learns to skip past.
        assert!(engine
            .answer_question(&theirs.id, "yes, yesterday", "agent-a", 600)
            .unwrap());
        let after = call(
            &engine,
            &json!({ "name": "task_claim", "arguments": { "task_id": mine.id, "step": "renew", "agent": "agent-a" } }),
        )
        .unwrap();
        let after_body: Value =
            serde_json::from_str(after["content"][0]["text"].as_str().unwrap()).unwrap();
        assert!(after_body.get("waiting_on_you").is_none());
        assert_eq!(after_body["paused_by_you"][0]["task_id"], paused.id);
    }

    #[test]
    fn claim_and_next_task_surface_governing_clauses_on_pickup() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship search", "add search", None)
            .unwrap();
        let node = "artifact:src/search.rs";
        engine
            .link_goal_to_artifact(&goal.id, &[node.into()], ArtifactBindingMode::Governed)
            .unwrap();
        let task = engine.create_task(&goal.id, "wire search", "done").unwrap();
        let open_next = engine
            .create_task(&goal.id, "polish search", "done")
            .unwrap();

        // claim_task surfaces what governs the work on a won claim.
        let claimed = call(
            &engine,
            &json!({ "name": "task_claim", "arguments": { "task_id": task.id, "step": "claim", "agent": "agent-a" } }),
        )
        .unwrap();
        let body: Value =
            serde_json::from_str(claimed["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(body["won"], true);
        assert_eq!(body["governing"][0]["goal"]["id"], goal.id);

        // next_task surfaces the same in structuredContent and the Markdown card.
        let next = call(
            &engine,
            &json!({ "name": "task_query", "arguments": { "view": "next" } }),
        )
        .unwrap();
        assert_eq!(next["structuredContent"]["id"], open_next.id);
        assert_eq!(
            next["structuredContent"]["governing"][0]["goal"]["id"],
            goal.id
        );
        assert!(next["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("Governed by"));

        // A task whose goal governs no code surfaces an empty list, cleanly.
        let free = engine
            .define_goal(GoalKind::Objective, "Free work", "loose", None)
            .unwrap();
        let ftask = engine.create_task(&free.id, "loose", "x").unwrap();
        let claimed_free = call(
            &engine,
            &json!({ "name": "task_claim", "arguments": { "task_id": ftask.id, "step": "claim", "agent": "agent-b" } }),
        )
        .unwrap();
        let free_body: Value =
            serde_json::from_str(claimed_free["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(free_body["won"], true);
        assert!(free_body["governing"].as_array().unwrap().is_empty());
    }

    /// A scoped claim used to report only the task goal's bindings, hiding a
    /// different goal that governed the declared path. The response must name
    /// that goal and the `also_serves` correction before work begins, while a
    /// covered or unbound path must not manufacture the warning.
    #[test]
    fn scoped_claim_surfaces_actionable_cross_goal_advice() {
        let engine = Lodestar::open_in_memory().unwrap();
        let delivery = engine
            .define_goal(
                GoalKind::Objective,
                "Ship checkout",
                "deliver checkout",
                None,
            )
            .unwrap();
        let governing = engine
            .define_goal(
                GoalKind::Constraint,
                "Payments boundary",
                "Payment code stays isolated.",
                None,
            )
            .unwrap();
        engine
            .link_goal_to_artifact(
                &delivery.id,
                &["artifact:src/checkout.rs".to_string()],
                ArtifactBindingMode::Governed,
            )
            .unwrap();
        engine
            .link_goal_to_artifact(
                &governing.id,
                &["artifact:crates/pay/src/lib.rs".to_string()],
                ArtifactBindingMode::Governed,
            )
            .unwrap();

        let cross = engine
            .create_task(&delivery.id, "Wire payment", "done")
            .unwrap();
        let claimed = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": cross.id,
                    "step": "claim",
                    "agent": "agent-a",
                    "paths": ["crates/pay/**"]
                }
            }),
        )
        .unwrap();
        let body: Value =
            serde_json::from_str(claimed["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(body["scope_advice"]["disposition"], "review");
        assert_eq!(
            body["scope_advice"]["governing"][0]["goal"]["id"],
            governing.id
        );
        assert!(body["scope_advice"]["findings"]
            .as_array()
            .unwrap()
            .iter()
            .any(|finding| finding.as_str().unwrap().contains("also_serves")));
        assert!(body["governing"]
            .as_array()
            .unwrap()
            .iter()
            .any(|clause| clause["goal"]["id"] == governing.id));

        let covered = engine
            .create_task(&delivery.id, "Wire covered payment", "done")
            .unwrap();
        let claimed_covered = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": covered.id,
                    "step": "claim",
                    "agent": "agent-b",
                    "paths": ["crates/pay/**"],
                    "also_serves": [governing.id]
                }
            }),
        )
        .unwrap();
        let covered_body: Value =
            serde_json::from_str(claimed_covered["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(covered_body["scope_advice"]["disposition"], "advise");

        let unbound = engine
            .create_task(&delivery.id, "Touch unbound file", "done")
            .unwrap();
        let claimed_unbound = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": unbound.id,
                    "step": "claim",
                    "agent": "agent-c",
                    "paths": ["src/unbound.rs"]
                }
            }),
        )
        .unwrap();
        let unbound_body: Value =
            serde_json::from_str(claimed_unbound["content"][0]["text"].as_str().unwrap()).unwrap();
        assert!(unbound_body.get("scope_advice").is_none());
        assert_eq!(unbound_body["governing"].as_array().unwrap().len(), 1);
        assert_eq!(unbound_body["governing"][0]["goal"]["id"], delivery.id);
    }

    /// Re-claiming with omitted scope fields used to convert omission into two
    /// empty arrays and erase the path linkage `merge_evidence` needs. Omission
    /// preserves each field; only an explicitly supplied array replaces it.
    #[test]
    fn reclaim_preserves_omitted_scope_fields_and_replaces_explicit_ones() {
        let definition = definitions()
            .into_iter()
            .find(|definition| definition["name"] == "task_claim")
            .unwrap();
        assert!(definition["inputSchema"]["properties"]["paths"]
            .get("default")
            .is_none());
        assert!(definition["inputSchema"]["properties"]["symbols"]
            .get("default")
            .is_none());

        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship scope", "preserve scope", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Scoped work", "done").unwrap();
        let original = TaskScope {
            paths: vec!["src/**".to_string()],
            symbols: vec!["symbol:src/lib.rs:run".to_string()],
        };

        let first = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": task.id,
                    "step": "claim",
                    "agent": "agent-a",
                    "paths": original.paths,
                    "symbols": original.symbols
                }
            }),
        )
        .unwrap();
        let first_body: Value =
            serde_json::from_str(first["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(first_body["won"], true);
        assert_eq!(engine.task_scope(&task.id).unwrap(), original);

        let reclaimed = call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": task.id,
                    "step": "claim",
                    "agent": "agent-a"
                }
            }),
        )
        .unwrap();
        let reclaimed_body: Value =
            serde_json::from_str(reclaimed["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(reclaimed_body["won"], true);
        assert_eq!(engine.task_scope(&task.id).unwrap(), original);

        call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": task.id,
                    "step": "claim",
                    "agent": "agent-a",
                    "paths": []
                }
            }),
        )
        .unwrap();
        assert_eq!(
            engine.task_scope(&task.id).unwrap(),
            TaskScope {
                paths: Vec::new(),
                symbols: original.symbols.clone(),
            }
        );

        call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": task.id,
                    "step": "claim",
                    "agent": "agent-a",
                    "symbols": ["symbol:src/new.rs:start"]
                }
            }),
        )
        .unwrap();
        assert_eq!(
            engine.task_scope(&task.id).unwrap(),
            TaskScope {
                paths: Vec::new(),
                symbols: vec!["symbol:src/new.rs:start".to_string()],
            }
        );

        let fresh = engine
            .create_task(&goal.id, "Unscoped work", "done")
            .unwrap();
        call(
            &engine,
            &json!({
                "name": "task_claim",
                "arguments": {
                    "task_id": fresh.id,
                    "step": "claim",
                    "agent": "agent-b"
                }
            }),
        )
        .unwrap();
        assert_eq!(engine.task_scope(&fresh.id).unwrap(), TaskScope::default());
    }
